class Worker {
  role = "general";
  constructor() {
    this.intro = this.describe();
  }
  describe() {
    return `worker:${this.role}`;
  }
}

class Builder extends Worker {
  role = "builder";
  describe() {
    return `builder:${this.role}`;
  }
}

const b = new Builder();
console.log(b.intro);
console.log(b.describe());
console.log(b.role);
